  var POSES = ['scroll', 'mask', 'column', 'flute', 'pensive', 'tablet', 'lyre', 'globe', 'tragedy'];
  var POSE_LABEL = { scroll: 'con un pergamino', mask: 'con una máscara', column: 'apoyada en una columna', flute: 'tocando la flauta', pensive: 'pensativa', tablet: 'con una tablilla', lyre: 'con una lira', globe: 'junto a un globo', tragedy: 'alzando una máscara' };

